const descriptions={music:['Music','Browse and search your tracks','Bring the audio files on your device together in one place. Browse your library or search for a specific song.'],albums:['Albums','Listen by album','Browse the albums in your local library and play their tracks in order.'],artists:['Artists','Find music by artist','Browse the artists in your library to find their songs and albums.'],playlists:['Playlists','Organize your listening','Create playlists and save favorite tracks for quick access.'],offline:['Offline','Play your local files','Music stored on your device plays without an internet connection. Ads and optional online features require a connection.']};
const tabs=[...document.querySelectorAll('[data-tab]')];function activate(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1});const [label,title,copy]=descriptions[tab.dataset.tab];document.querySelector('.detail-label').textContent=label;document.querySelector('#detail-title').textContent=title;document.querySelector('#detail-copy').textContent=copy;document.querySelector('#collection-panel').setAttribute('aria-labelledby',tab.id)}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',event=>{let next;if(['ArrowDown','ArrowRight'].includes(event.key))next=(index+1)%tabs.length;if(['ArrowUp','ArrowLeft'].includes(event.key))next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();activate(tabs[next]);tabs[next].focus()}})});
